package dev.droidrt.agent;

import android.content.Context;
import android.content.SharedPreferences;

import java.util.regex.Pattern;

/**
 * Holds the shared secret used to authenticate host connections.
 *
 * The key is 32 random bytes generated by the host and delivered as 64 hex
 * characters through {@link KeyReceiver}. It is stored in the app's private
 * SharedPreferences (MODE_PRIVATE), so only this app and root can read it.
 * The HMAC key is the 32 decoded bytes, not the hex text.
 */
final class AgentKey {
    private static final String PREFS = "droidrt_agent";
    private static final String PREF_KEY = "hmac_key";
    private static final Pattern KEY_HEX = Pattern.compile("^[0-9a-fA-F]{64}$");

    private static Context appContext;

    private AgentKey() {
    }

    static synchronized void init(Context context) {
        if (appContext == null) {
            appContext = context.getApplicationContext();
        }
    }

    static boolean isValidHex(String hex) {
        return hex != null && KEY_HEX.matcher(hex).matches();
    }

    /** Stores a new key, replacing any previous one. Returns false on invalid input. */
    static boolean store(Context context, String hex) {
        if (!isValidHex(hex)) {
            return false;
        }
        init(context);
        return prefs(context).edit().putString(PREF_KEY, hex.toLowerCase(java.util.Locale.ROOT)).commit();
    }

    /** Returns the 32 key bytes, or null when no key has been delivered yet. */
    static byte[] load() {
        Context context;
        synchronized (AgentKey.class) {
            context = appContext;
        }
        if (context == null) {
            return null;
        }
        String hex = prefs(context).getString(PREF_KEY, null);
        return isValidHex(hex) ? Hex.decode(hex) : null;
    }

    private static SharedPreferences prefs(Context context) {
        return context.getApplicationContext().getSharedPreferences(PREFS, Context.MODE_PRIVATE);
    }
}
